LOBBY_SHA256 = '52528ddd929da8b149feb189406b1cd0f7d4d76d57eb832cdd011c177383b561'


def fixture():
    raw = zlib.decompress(base64.b85decode(''.join(_BUNDLE)))
    assert hashlib.sha256(raw).hexdigest() == FIXTURE_SHA256
    values = json.loads(raw)
    failed_raw, ready_raw = values.pop('failed_raw'), values.pop('ready_raw')
    assert hashlib.sha256(failed_raw.encode()).hexdigest() == 'cb64cec0472f9a23d176fbf1e98710aee72b0c195f03ca62b60355f7d994213f'
    assert hashlib.sha256(ready_raw.encode()).hexdigest() == 'ffbc2f9482ab1c029c3764411d517468d142880434071ca1f59b2b06487a5194'
    F, ready = json.loads(failed_raw), json.loads(ready_raw)
    return {**values, 'F': F, 'ready': ready}


def lobby_fixture(audit_until=1791423525.0):
    value = fixture()
    raw = zlib.decompress(base64.b85decode(''.join(_LOBBY_BUNDLE)))
    assert hashlib.sha256(raw).hexdigest() == LOBBY_SHA256
    suffix = json.loads(raw)
    for field in ('rows', 'events'):
        value[field].extend(row for row in suffix[field] if row['time'] <= audit_until)
    value['until'] = audit_until
    _sort(value)
    return value


def validate(value):
    return failed_contract.failed_history(*(value[k] for k in ('rows', 'events', 'ready', 'F', 'until')))


def _one(value, name, direction):
    return next(row for row in value['rows'] if (row.get('name'), row.get('direction')) == (name, direction))


def _logout_update(value):
    return next(row for row in value['rows'] if row.get('direction') == 'from_native' and
        row.get('name') == 'SMSG_UPDATE_OBJECT' and any(rec.get('guid') == 2 and
            rec.get('fields', {}).get(INDEX['UNIT_FIELD_FLAGS']) == 0x40008 for rec in records(bytes.fromhex(row['body']))))


def _sort(value):
    value['rows'].sort(key=lambda row: row['time'])
    value['events'].sort(key=lambda row: row['time'])


def _removal(guid, owner, timestamp):
    octets = guid.to_bytes(8, 'little')
    raw = Writer().pack('HI', 0, 1).pack('BI', 3, 1).pack('B', sum(bool(v) << i for i, v in enumerate(octets)))
    raw.raw(bytes(v for v in octets if v))
    return {'session': owner, 'name': 'SMSG_UPDATE_OBJECT', 'direction': 'from_native',
        'time': timestamp, 'body': raw.finish().hex()}


def test_actual_original_login_idle_and_logout_are_closed_excluded_history(monkeypatch):
    value = fixture()
    before = deepcopy(value)
    def forbidden(*args, **kwargs):
        raise AssertionError('failed-history proof attempted filesystem, Git, process or client access')
    with monkeypatch.context() as blocked:
        for name in ('read_bytes', 'read_text', 'open', 'stat', 'is_file', 'is_dir', 'is_symlink', 'resolve'):
            blocked.setattr(Path, name, forbidden)
        for name in ('check_output', 'run', 'Popen'):
            blocked.setattr(subprocess, name, forbidden)
        for name in ('open', 'stat', 'lstat'):
            blocked.setattr(os, name, forbidden)
        blocked.setattr(builtins, 'open', forbidden)
        proof = validate(value)
        repeated = validate(value)
    assert value == before
    assert proof['schema'] == failed_contract.SCHEMA
    assert proof['qualification_excluded'] is True
    assert proof['audit_until'] == value['until']
    serialized = json.dumps(proof, sort_keys=True, separators=(',', ':'), allow_nan=False)
    assert len(serialized.encode()) < 100_000
    assert json.loads(serialized) == proof
    assert serialized == json.dumps(repeated, sort_keys=True, separators=(',', ':'), allow_nan=False)
    assert hashlib.sha256((json.dumps(value['F'], indent=2) + '\n').encode()).hexdigest() == 'cb64cec0472f9a23d176fbf1e98710aee72b0c195f03ca62b60355f7d994213f'
    assert proof['native_original']['pose'] == {'stand': 0, 'sheath': 0}
    assert proof['native_original']['afk'] is False
    assert proof['native_original']['unit_flags'] == 8
    assert proof['native_original']['native_rooted'] is False
    assert proof['native_final']['pose'] == {'stand': 1, 'sheath': 0}
    assert proof['native_final']['afk'] is True
    assert proof['native_final']['unit_flags'] == 0x40008
    assert proof['native_final']['native_rooted'] is True
    assert proof['original_objects']['2']['53'] == 8
    assert proof['final_objects']['2']['53'] == 8 | 0x40000
    assert proof['original_objects']['2']['117'] == proof['final_objects']['2']['117'] == 0x11000000
    assert proof['final_objects']['2']['68'] == 1 and proof['final_objects']['2']['148'] == 2
    assert proof['automatic_idle']['afk_body_retained'] is False
    assert proof['logout']['complete']['time'] == 1791422949.002927
    assert proof['logout']['connection_closed']['time'] == value['until']
    assert len(proof['original_objects']) == 6
    assert proof['original_sql_inventory'] == value['ready']['all_offline_snapshot']['2']['inventory']
    assert value['F']['completed'] is False
    assert value['F']['phase'] == 'bags_swap_entry_started'
    assert _one(value, 'CMSG_LOGOUT_REQUEST', 'from_client')['time'] == 1791422929.6677074
    assert _one(value, 'SMSG_LOGOUT_COMPLETE', 'from_native')['time'] == 1791422949.002927
    assert value['until'] == 1791422949.0036314
    creation = next(rec for row in value['F']['raw_entry_packets'] if
        (row.get('name'), row.get('direction')) == ('SMSG_UPDATE_OBJECT', 'from_native')
        for rec in records(bytes.fromhex(row['body'])) if rec.get('guid') == 2 and rec['update_type'] == 1)
    assert creation['fields'][53] == 8
    assert creation['fields'][117] == 0x11000000
    assert records(bytes.fromhex(_logout_update(value)['body']))[0]['fields'][53] == 8 | 0x40000


def test_closed_failed_history_does_not_admit_the_normal_occupied_swap_guard():
    value = fixture()
    proof = validate(value)
    with pytest.raises(RuntimeError, match='bag swap refuses'):
        failed_contract.contract.forbidden_packets(value['rows'], value['ready']['native_session'],
            value['F']['started_at'], value['until'], login_sync=proof['login_sync'])


@pytest.mark.parametrize('audit_until', [1791423505.0, 1791423525.0])
@pytest.mark.parametrize('include_lobby', [False, True])
def test_audit_cutoff_extends_beyond_physical_close_without_another_actor_input(audit_until, include_lobby):
    value = lobby_fixture(audit_until) if include_lobby else fixture()
    value['until'] = audit_until
    before = deepcopy(value)
    proof = validate(value)
    assert value == before
    assert proof['qualification_excluded'] is True
    assert proof['until'] == proof['logout']['connection_closed']['time'] == 1791422949.0036314
    assert proof['audit_until'] == audit_until
    assert proof['native_original']['pose'] == {'stand': 0, 'sheath': 0}
    assert proof['native_final']['pose'] == {'stand': 1, 'sheath': 0}
    assert proof['native_final']['unit_flags'] == 0x40008
    if include_lobby:
        assert any(row['name'] == 'CMSG_ENUM_CHARACTERS' for row in value['rows']
            if row['time'] > proof['until'])
        assert all(row['session'] == 'c6195b73' for row in value['rows'] if row['time'] > proof['until'])


@pytest.mark.parametrize('fault', ['owner_cast', 'old_physical_cast', 'metadata_afk',
    'another_owner_login', 'foreign_actor_login', 'late_raw_login', 'late_raw_move', 'directionless_move',
    'late_swap', 'late_target', 'housekeeping_stand', 'nonroutine', 'unmatched_ping',
    'changed_ping_size', 'unmatched_query', 'changed_closed_time', 'missing_endpoint',
    'old_physical_ping', 'late_native_root', 'late_native_owner_update',
    'foreign_player_creation', 'foreign_forwarded_movement', 'foreign_auth_invalid_time'])
def test_audit_suffix_rejects_actor_activity_unmatched_routines_or_lost_endpoint(fault):
    value = lobby_fixture()
    owner, physical, timestamp = value['ready']['native_session'], '04aa8d2f', 1791423515.0
    if fault in ('owner_cast', 'old_physical_cast', 'late_raw_login', 'late_raw_move', 'late_swap', 'late_target',
            'housekeeping_stand', 'nonroutine'):
        name, raw = {
            'owner_cast': ('CMSG_CAST_SPELL', ''), 'old_physical_cast': ('CMSG_CAST_SPELL', ''),
            'late_raw_login': ('CMSG_PLAYER_LOGIN', '0200000000000000'),
            'late_raw_move': ('CMSG_MOVE_HEARTBEAT', ''), 'late_swap': ('CMSG_SWAP_INV_ITEM', '0001'),
            'late_target': ('CMSG_SET_SELECTION', ''),
            'housekeeping_stand': ('CMSG_STAND_STATE_CHANGE', '00'),
            'nonroutine': ('CMSG_UNKNOWN_CLIENT_COMMAND', '')}[fault]
        value['rows'].append({'session': physical if fault == 'old_physical_cast' else owner,
            'name': name, 'direction': 'from_client', 'body': raw, 'time': timestamp})
    elif fault == 'metadata_afk':
        value['events'].append({'session': owner, 'name': 'CMSG_CHAT_MESSAGE_AFK', 'direction': 'from_client',
            'event': 'modern_packet', 'bytes': 5, 'time': timestamp})
    elif fault in ('another_owner_login', 'foreign_actor_login'):
        value['events'].append({'session': owner if fault == 'another_owner_login' else 'new-foreign-instance',
            'event': 'instance_authenticated', 'account_id': 2, 'time': timestamp})
    elif fault in ('foreign_player_creation', 'foreign_forwarded_movement'):
        native = value['F']['native_before_entry']
        pose = [native[k] for k in ('position_x', 'position_y', 'position_z', 'orientation')]
        value['events'].append({'session': 'new-foreign-instance', 'guid': 2, 'map': 0,
            'event': 'native_player_created' if fault == 'foreign_player_creation' else 'movement_forwarded',
            'name': 'SMSG_UPDATE_OBJECT' if fault == 'foreign_player_creation' else 'CMSG_MOVE_HEARTBEAT',
            'position': pose, 'time': timestamp})
    elif fault == 'foreign_auth_invalid_time':
        for invalid_time in ('missing', None, float('nan'), float('inf')):
            changed = deepcopy(value)
            event = {'session': 'new-foreign-instance', 'event': 'instance_authenticated', 'account_id': 2}
            if invalid_time != 'missing': event['time'] = invalid_time
            changed['events'].append(event)
            with pytest.raises(RuntimeError):
                validate(changed)
        return
    elif fault == 'directionless_move':
        value['events'].append({'session': owner, 'name': 'CMSG_MOVE_HEARTBEAT',
            'event': 'unmapped_client_packet', 'bytes': 1, 'time': timestamp})
    elif fault in ('unmatched_ping', 'changed_ping_size', 'unmatched_query'):
        name = 'CMSG_PING' if fault != 'unmatched_query' else 'CMSG_SERVER_TIME_OFFSET_REQUEST'
        post = next(row for row in value['events'] if row.get('name') == name and
            row.get('direction') == 'from_client' and row['time'] > 1791422949.0036314)
        if fault == 'changed_ping_size': post['bytes'] = 9
        else: value['events'].remove(post)
    elif fault in ('changed_closed_time', 'missing_endpoint'):
        close = next(row for row in value['events'] if row.get('event') == 'world_connection_closed')
        if fault == 'changed_closed_time': close['time'] += 10
        else: value['events'].remove(close)
    elif fault == 'old_physical_ping':
        value['events'].append({'session': physical, 'name': 'CMSG_PING', 'direction': 'from_client',
            'event': 'modern_packet', 'bytes': 8, 'time': timestamp})
    elif fault == 'late_native_root':
        value['rows'].append({**_one(value, 'SMSG_MOVE_ROOT', 'from_native'), 'time': timestamp})
    elif fault == 'late_native_owner_update':
        value['rows'].append(dict(native_packet({INDEX['UNIT_FIELD_HEALTH']: 60},
            creation=False, time=timestamp), session=owner))
    _sort(value)
    with pytest.raises(RuntimeError):
        validate(value)


@pytest.mark.parametrize('fault', ['missing_original', 'changed_boot', 'extra_swap', 'later_movement',
    'second_sit', 'extra_afk', 'cast_metadata', 'missing_root', 'foreign_root', 'unrooted_flags',
    'native_health', 'temporary_item_change', 'logout_cancel', 'missing_complete', 'changed_delivery',
    'short_logout', 'missing_close', 'foreign_close', 'early_close', 'failed_success', 'foreign_ready',
    'temporary_health_restored', 'owned_item_removal', 'unseen_item_creation', 'unseen_item_removal',
    'repeated_login_metadata', 'foreign_late_login_metadata', 'late_movement_effect',
    'extra_unroot', 'invented_root_ack', 'second_root', 'late_logout'])
def test_failed_history_rejects_another_input_changed_native_field_or_unclosed_logout(fault):
    value = fixture()
    owner = value['ready']['native_session']
    if fault == 'missing_original': value['rows'].pop(0)
    elif fault == 'changed_boot':
        _one(value, 'CMSG_MOVE_HEARTBEAT', 'from_client')['body'] += '00'
    elif fault in ('extra_swap', 'later_movement', 'logout_cancel'):
        name = {'extra_swap': 'CMSG_SWAP_INV_ITEM', 'later_movement': 'CMSG_MOVE_HEARTBEAT',
            'logout_cancel': 'CMSG_LOGOUT_CANCEL'}[fault]
        value['rows'].append({'session': owner, 'name': name, 'direction': 'from_client',
            'body': '0001' if fault == 'extra_swap' else '', 'time': value['F']['finished_at'] + 1})
    elif fault == 'second_sit':
        stand = [row for row in value['rows'] if row.get('name') in
            ('CMSG_STAND_STATE_CHANGE', 'CMSG_STANDSTATECHANGE', 'SMSG_STAND_STATE_UPDATE')]
        value['rows'].extend({**row, 'time': row['time'] + 100} for row in stand)
    elif fault == 'extra_afk':
        afk = [row for row in value['events'] if row.get('name') in ('CMSG_CHAT_MESSAGE_AFK', 'CMSG_MESSAGECHAT_AFK')]
        value['events'].extend({**row, 'time': row['time'] + 100} for row in afk)
    elif fault == 'cast_metadata':
        value['events'].append({'event': 'modern_packet', 'session': '04aa8d2f', 'name': 'CMSG_CAST_SPELL',
            'direction': 'from_client', 'bytes': 20, 'time': value['F']['finished_at'] + 1})
    elif fault == 'missing_root':
        value['rows'] = [row for row in value['rows'] if row.get('name') != 'SMSG_MOVE_ROOT']
    elif fault == 'foreign_root': _one(value, 'SMSG_MOVE_ROOT', 'from_native')['body'] = '100400000000'
    elif fault == 'extra_unroot':
        value['rows'].append({**_one(value, 'SMSG_MOVE_ROOT', 'from_native'),
            'name': 'SMSG_MOVE_UNROOT', 'time': value['F']['finished_at'] + 1})
    elif fault == 'invented_root_ack':
        value['rows'].append({'session': owner, 'name': 'CMSG_MOVE_ROOT_ACK', 'direction': 'from_client',
            'body': '', 'time': value['F']['finished_at'] + 1})
    elif fault in ('second_root', 'late_logout'):
        row = _one(value, 'SMSG_MOVE_ROOT' if fault == 'second_root' else 'CMSG_LOGOUT_REQUEST',
            'from_native' if fault == 'second_root' else 'from_client')
        value['rows'].append({**row, 'time': row['time'] + 1})
    elif fault in ('unrooted_flags', 'native_health'):
        row = _logout_update(value)
        fields = {53: 8 if fault == 'unrooted_flags' else 0x40008, 61: 49, 73: 0, 77: 0}
        if fault == 'native_health': fields[INDEX['UNIT_FIELD_HEALTH']] = 59
        row['body'] = native_packet(fields, creation=False, time=row['time'])['body']
    elif fault == 'temporary_item_change':
        guid = (0x4000 << 48) | 41
        index = INDEX['ITEM_FIELD_STACK_COUNT']
        value['rows'].extend(dict(native_packet({index: count}, guid=guid, creation=False,
            time=value['F']['finished_at'] + offset), session=owner) for offset, count in ((1, 2), (2, 1)))
    elif fault == 'temporary_health_restored':
        value['rows'].extend(dict(native_packet({INDEX['UNIT_FIELD_HEALTH']: health}, creation=False,
            time=value['F']['finished_at'] + offset), session=owner) for offset, health in ((1, 59), (2, 60)))
    elif fault in ('owned_item_removal', 'unseen_item_removal'):
        guid = (0x4000 << 48) | (41 if fault == 'owned_item_removal' else 99)
        value['rows'].append(_removal(guid, owner, value['F']['finished_at'] + 1))
    elif fault == 'unseen_item_creation':
        fields = {INDEX['OBJECT_FIELD_ENTRY']: 6948, INDEX['ITEM_FIELD_STACK_COUNT']: 1,
            INDEX['ITEM_FIELD_OWNER']: 2, INDEX['ITEM_FIELD_CONTAINED']: 2}
        value['rows'].append(dict(native_packet(fields, guid=(0x4000 << 48) | 99, kind=1,
            creation=True, time=value['F']['finished_at'] + 1), session=owner))
    elif fault in ('repeated_login_metadata', 'foreign_late_login_metadata'):
        value['events'].append({'event': 'instance_authenticated', 'account_id': 2,
            'session': '04aa8d2f' if fault == 'repeated_login_metadata' else 'other-instance',
            'time': value['F']['finished_at'] + 1})
    elif fault == 'late_movement_effect':
        creation = next(rec for row in value['F']['raw_entry_packets'] if
            (row.get('name'), row.get('direction')) == ('SMSG_UPDATE_OBJECT', 'from_native')
            for rec in records(bytes.fromhex(row['body'])) if rec.get('guid') == 2 and rec['update_type'] == 1)
        value['events'].append({'event': 'movement_forwarded', 'session': '04aa8d2f',
            'name': 'CMSG_MOVE_HEARTBEAT', 'guid': 2, 'position': list(creation['movement']['position']),
            'time': value['F']['finished_at'] + 1})
    elif fault == 'missing_complete':
        value['rows'] = [row for row in value['rows'] if row.get('name') != 'SMSG_LOGOUT_COMPLETE']
    elif fault == 'changed_delivery': _one(value, 'SMSG_LOGOUT_COMPLETE', 'to_client')['body'] = '01'
    elif fault == 'short_logout':
        for row in value['rows']:
            if row.get('name') == 'SMSG_LOGOUT_COMPLETE': row['time'] -= 15
    elif fault == 'missing_close':
        value['events'] = [row for row in value['events'] if row.get('event') != 'world_connection_closed']
    elif fault in ('foreign_close', 'early_close'):
        row = next(row for row in value['events'] if row.get('event') == 'world_connection_closed')
        if fault == 'foreign_close': row['session'] = 'foreign'
        else: row['time'] = _one(value, 'CMSG_LOGOUT_REQUEST', 'from_client')['time'] - 1
    elif fault == 'failed_success': value['F']['completed'] = True
    elif fault == 'foreign_ready': value['ready']['native_session'] = 'foreign'
    _sort(value)
    with pytest.raises(RuntimeError):
        validate(value)
